function readState(stdout: string): { status?: string; outcome?: string } {
	const value: unknown = JSON.parse(stdout);
	if (typeof value !== "object" || value === null) throw new Error("estado inválido");
	const { status, outcome } = value as Record<string, unknown>;
	return { status: typeof status === "string" ? status : undefined, outcome: typeof outcome === "string" ? outcome : undefined };
