import { randomUUID } from "node:crypto";

import type { Context } from "@earendil-works/chord";
import {
	defineDoc,
	type ConversationId,
	type Session,
} from "@earendil-works/pi-durable";

export type ChargeProvider = {
	/**
	 * Idempotente por chave: repetir a mesma chave não cobra de novo e devolve
	 * o mesmo resultado.
	 */
	charge(
		key: string,
		amountCents: number,
	): Promise<{ key: string; amountCents: number }>;
};

export type ChargeResult = {
	status: "charged";
	key: string;
	amountCents: number;
};

type ChargeIntent = {
	key: string;
	amountCents: number;
};

/**
 * Intenção e resultado no mesmo documento, por conversa. A intenção é gravada
 * antes de qualquer efeito externo; é dela que a chave idempotente sai, então
 * a chave sobrevive a reinício e nunca é regerada para o mesmo requestId.
 */
const Charges = defineDoc<{
	intents: Record<string, ChargeIntent>;
	results: Record<string, ChargeResult>;
}>({
	kind: "app.charge",
	version: 1,
	scope: "conversation",
	history: "latest",
	fork: "initial",
	initial: () => ({ intents: {}, results: {} }),
	checkpointWhen: (_value, _ops, info) => info.deltasSinceBase >= 512,
});

export async function chargeOnce(
	session: Session,
	conversationId: ConversationId,
	requestId: string,
	amountCents: number,
	provider: ChargeProvider,
	context: Context,
): Promise<ChargeResult> {
	const state = await session.commit(async (tx) => {
		const charges = await tx.doc(Charges, conversationId);
		// Cópias: valores do draft viram overlay e não podem ser lidos depois que
		// o commit assenta.
		const stored = charges.results[requestId];
		if (stored !== undefined) {
			return {
				result: {
					status: "charged" as const,
					key: stored.key,
					amountCents: stored.amountCents,
				},
				intent: undefined,
			};
		}

		const existing = charges.intents[requestId];
		const intent: ChargeIntent = {
			key: existing?.key ?? randomUUID(),
			amountCents,
		};
		charges.intents[requestId] = intent;
		return { result: undefined, intent };
	}, context);

	if (state.result !== undefined) {
		if (state.result.amountCents !== amountCents) {
			throw new Error(
				`requestId ${requestId} já cobrado com ${state.result.amountCents} centavos`,
			);
		}
		return state.result;
	}

	if (state.intent === undefined) {
		throw new Error(`intenção ausente para ${requestId}`);
	}
	if (state.intent.amountCents !== amountCents) {
		throw new Error(
			`requestId ${requestId} já tem intenção de ${state.intent.amountCents} centavos`,
		);
	}

	const charged = await provider.charge(state.intent.key, amountCents);
	const result: ChargeResult = {
		status: "charged",
		key: charged.key,
		amountCents: charged.amountCents,
	};

	await session.commit(async (tx) => {
		const charges = await tx.doc(Charges, conversationId);
		charges.results[requestId] ??= result;
	}, context);

	return result;
}

export async function readCharge(
	session: Session,
	conversationId: ConversationId,
	requestId: string,
	context: Context,
): Promise<ChargeResult | undefined> {
	const charges = await session.snapshot(Charges, conversationId, context);
	return charges?.results[requestId];
}

import { spawn } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

// Invariante de docs/DURABILITY.md §2: efeito externo não pode duplicar
// quando o processo morre entre a chamada e o commit do resultado.
//
// O filho roda um Harness real sobre SQLite em arquivo e chama um provedor sem
// idempotência (cada cobrança vira uma linha no log). O kill é SIGKILL de
// dentro do processo, no ponto exato depois da cobrança e antes do commit.

const CHILD = fileURLToPath(new URL("./fixtures/effect-child.mjs", import.meta.url));
const TIMEOUT = 30_000;

interface Run {
	code: number | null;
	signal: NodeJS.Signals | null;
	stdout: string;
}

function runChild(
	mode: "crash" | "resume",
	db: string,
	effects: string,
	env: Record<string, string> = {},
): Promise<Run> {
	return new Promise((resolve, reject) => {
		const child = spawn(process.execPath, [CHILD, mode, db, effects], {
			env: { ...process.env, ...env },
			stdio: ["ignore", "pipe", "ignore"],
		});
		let stdout = "";
		child.stdout.on("data", (chunk: Buffer) => {
			stdout += chunk.toString();
		});
		child.on("error", reject);
		child.on("close", (code, signal) => {
			resolve({ code, signal, stdout });
		});
	});
}

async function charges(effects: string): Promise<string[]> {
	try {
		const text = await readFile(effects, "utf8");
		return text.split("\n").filter(Boolean);
	} catch {
		return [];
	}
}

async function withDb(run: (dir: string, db: string, effects: string) => Promise<void>) {
	const dir = await mkdtemp(join(tmpdir(), "durable-crash-"));
	try {
		await run(dir, join(dir, "session.sqlite"), join(dir, "effects.log"));
	} finally {
		await rm(dir, { recursive: true, force: true });
	}
}

describe("crash com efeito externo", () => {
	it(
		"SIGKILL depois da cobrança: resume completa sem cobrar duas vezes",
		async () => {
			await withDb(async (_dir, db, effects) => {
				const crashed = await runChild("crash", db, effects, { CRASH_AT: "after" });
				expect(crashed.signal).toBe("SIGKILL");
				expect(await charges(effects)).toEqual(["charge-1"]);

				const resumed = await runChild("resume", db, effects);
				expect(resumed.code).toBe(0);
				expect(JSON.parse(resumed.stdout) as { status: string }).toMatchObject({
					status: "terminal",
					outcome: "completed",
				});

				expect(await charges(effects)).toEqual(["charge-1"]);
			});
		},
		TIMEOUT,
	);

	it(
		"SIGKILL antes da cobrança: resume cobra exatamente uma vez",
		async () => {
			await withDb(async (_dir, db, effects) => {
				const crashed = await runChild("crash", db, effects, { CRASH_AT: "before" });
				expect(crashed.signal).toBe("SIGKILL");
				expect(await charges(effects)).toEqual([]);

				const resumed = await runChild("resume", db, effects);
				expect(resumed.code).toBe(0);
				expect(await charges(effects)).toEqual(["charge-1"]);
			});
		},
		TIMEOUT,
	);

	it(
		"resume repetido sobre tarefa terminal não cobra de novo",
		async () => {
			await withDb(async (_dir, db, effects) => {
				await runChild("crash", db, effects, { CRASH_AT: "after" });
				await runChild("resume", db, effects);
				const again = await runChild("resume", db, effects);

				expect(again.code).toBe(0);
				expect(await charges(effects)).toEqual(["charge-1"]);
			});
		},
		TIMEOUT,
	);

	it(
		"chave estável no provedor idempotente: crash não cobra duas vezes",
		async () => {
			await withDb(async (_dir, db, effects) => {
				const crashed = await runChild("crash", db, effects, {
					CRASH_AT: "after",
					TASK: "keyed",
				});
				expect(crashed.signal).toBe("SIGKILL");
				expect(await charges(effects)).toEqual(["charge-1"]);

				const resumed = await runChild("resume", db, effects, { TASK: "keyed" });
				expect(resumed.code).toBe(0);
				expect(await charges(effects)).toEqual(["charge-1"]);
			});
		},
		TIMEOUT,
	);
});

// Processo filho do teste de crash. Não é importado pelo vitest: roda em um
// processo Node separado para que SIGKILL seja real.
//
// uso: node effect-child.mjs <crash|resume> <db> <effects.log>
//   CRASH_AT=before|after   ponto do kill no modo crash
//   TASK=query|keyed        estratégia de reconciliação
import { appendFileSync, existsSync, readFileSync } from "node:fs";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import { createModels } from "@earendil-works/pi-ai/models";
import {
	createRegistry,
	defineExtension,
	defineTask,
	Harness,
} from "@earendil-works/pi-durable";
import { openNodeSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/node";

const [mode, dbPath, effectLog] = process.argv.slice(2);
if (!mode || !dbPath || !effectLog) {
	throw new Error("uso: effect-child.mjs <crash|resume> <db> <effects.log>");
}

const crashAt = mode === "crash" ? (process.env.CRASH_AT ?? "") : "";
const keyed = process.env.TASK === "keyed";

function chargedKeys() {
	if (!existsSync(effectLog)) return [];
	return readFileSync(effectLog, "utf8").split("\n").filter(Boolean);
}

/** Provedor sem idempotência: cada chamada cobra de novo. */
function charge(key) {
	appendFileSync(effectLog, `${key}\n`);
}

/** Provedor idempotente por chave: repetir a mesma chave não cobra de novo. */
function chargeWithKey(key) {
	if (!chargedKeys().includes(key)) charge(key);
}

function makeCharge(name, applyCharge) {
	return defineTask({
		name,
		version: 1,
		initial: (input) => ({ phase: "charge", input }),
		phases: {
			charge: async (task, runtime, context) => {
				const { key } = task.state.checkpoint.input;

				if (crashAt === "before") process.kill(process.pid, "SIGKILL");

				applyCharge(key);

				if (crashAt === "after") process.kill(process.pid, "SIGKILL");

				await runtime.commit(
