export async function ask(session: AgentSession, prompt: string, context: Context): Promise<AskResult> {
	const submission = await session.conversation.submit(
		{ type: "input", content: prompt, requestId: randomUUID() },
		context,
	);
	const settled = await submission.wait(context);
	if (settled.status !== "done") {
		return { submissionId: submission.id, status: settled.status, reason: settled.reason };
	}
	const entry = await session.conversation.commit((tx) => tx.entry(AssistantEntry, settled.answer), context);
	const answer = textOf(entry);
	return answer === undefined
		? { submissionId: submission.id, status: "done" }
		: { submissionId: submission.id, status: "done", answer };
}
