import { randomUUID } from "node:crypto";

import type { Context } from "@earendil-works/chord";
import { createModels, type Models } from "@earendil-works/pi-ai";
import {
	AssistantEntry,
	createRegistry,
	Harness,
	type Conversation,
	type EntryRecord,
	type ModelRef,
	type SubmissionId,
} from "@earendil-works/pi-durable";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { openNodeSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";

/**
 * Prompt padrão. Instruções de projeto (`AGENTS.md`) entram no M2; até lá o
 * agente só sabe o que está aqui e o que a tool `read` devolver.
 */
export const DEFAULT_INSTRUCTIONS = [
	"Você é um agente de código rodando sobre um harness durável.",
	"Use as tools para inspecionar e alterar arquivos. Prefira editar a reescrever.",
	"Responda curto: o que mudou, o que falhou, e o próximo passo.",
].join("\n");

export type AgentOptions = {
	readonly dbPath: string;
	readonly cwd: string;
	readonly model: ModelRef;
	readonly instructions?: string;
	/** Injetável para teste; em produção, o catálogo do pi-ai. */
	readonly models?: Models;
};

export type AgentSession = {
	readonly harness: Harness;
	readonly conversation: Conversation;
};

export type AskOutcome = {
	readonly submissionId: SubmissionId;
	readonly status: "done" | "unanswered";
	readonly answer?: string;
	readonly reason?: string;
};

/** Registro de tools do agente: as quatro de código, nada além disso no M0. */
export function createAgentRegistry() {
	const registry = createRegistry();
	registry.install(CodingTools);
	return registry;
}

/**
 * Abre o Harness sobre um arquivo SQLite e devolve a conversa raiz já
 * configurada. Um processo por storage: quem chama isto é dono do arquivo.
 */
export async function openAgent(
	options: AgentOptions,
	context: Context,
): Promise<AgentSession> {
	const storage = await openNodeSqliteStorage(options.dbPath);
	const harness = await Harness.open(
		storage,
		{
			models: options.models ?? createModels(),
			registry: createAgentRegistry(),
			env: ({ cwd }) => new NodeExecutionEnv({ cwd: cwd ?? options.cwd }),
		},
		context,
	);
	const conversation = await harness.root(context, {
		agent: {
			model: options.model,
			instructions: options.instructions ?? DEFAULT_INSTRUCTIONS,
		},
	});
	return { harness, conversation };
}

/**
 * Submete o prompt e espera o desfecho. O `requestId` é gerado uma vez: reenviar
 * a mesma chamada não duplica a entrada.
 */
export async function ask(
	session: AgentSession,
	prompt: string,
	context: Context,
): Promise<AskOutcome> {
	const submission = await session.conversation.submit(
		{ type: "input", content: prompt, requestId: randomUUID() },
		context,
	);
	const settled = await submission.wait(context);

	if (settled.status !== "done") {
		return {
			submissionId: submission.id,
			status: "unanswered",
			reason: settled.reason,
		};
	}

	const entry = await session.conversation.commit(
		(tx) => tx.entry(AssistantEntry, settled.answer),
		context,
	);
	const answer = assistantText(entry);
	return answer === undefined
		? { submissionId: submission.id, status: "done" }
		: { submissionId: submission.id, status: "done", answer };
}

export async function closeAgent(
	session: AgentSession,
	context: Context,
): Promise<void> {
	await session.harness.close(context);
}

/** Texto da resposta final; pensamento e tool calls ficam de fora. */
function assistantText(entry: EntryRecord | undefined): string | undefined {
	const message = entry?.model?.[0];
	if (message === undefined || message.role !== "assistant") return undefined;
	const text = message.content
		.filter((block) => block.type === "text")
		.map((block) => block.text)
		.join("");
	return text === "" ? undefined : text;
}

import { randomBytes } from "node:crypto";
import { mkdir, readdir, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

export type SessionInfo = {
	readonly id: string;
	readonly path: string;
	readonly modifiedAt: number;
};

const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

/** `$DURABLE_PI_SESSION_DIR`, senão `$XDG_DATA_HOME/durable-pi/sessions`, senão `~/.local/share/...`. */
export function defaultSessionDir(env: NodeJS.ProcessEnv = process.env): string {
	const explicit = env["DURABLE_PI_SESSION_DIR"];
	if (explicit !== undefined && explicit !== "") return explicit;
	const dataHome = env["XDG_DATA_HOME"];
	const base =
		dataHome !== undefined && dataHome !== ""
			? dataHome
			: join(homedir(), ".local", "share");
	return join(base, "durable-pi", "sessions");
}

export function sessionPath(dir: string, id: string): string {
	assertSessionId(id);
	return join(dir, `${id}.sqlite`);
}

/** Ordenável por nome: `20261022T120000-4f3a1c`. */
export function newSessionId(now: Date = new Date()): string {
	const stamp = now
		.toISOString()
		.replace(/\.\d+Z$/, "")
		.replace(/[-:]/g, "");
	return `${stamp}-${randomBytes(3).toString("hex")}`;
}

export async function ensureSessionDir(dir: string): Promise<void> {
	await mkdir(dir, { recursive: true });
}

/** Sessões em disco, mais recente primeiro. Arquivos que não são `.sqlite` ficam de fora. */
export async function listSessions(dir: string): Promise<SessionInfo[]> {
	const entries = await readdir(dir).catch(() => [] as string[]);
	const sessions: SessionInfo[] = [];
	for (const name of entries) {
		if (!name.endsWith(".sqlite")) continue;
		const id = name.slice(0, -".sqlite".length);
		if (!ID_PATTERN.test(id)) continue;
		const info = await stat(join(dir, name)).catch(() => undefined);
		if (info === undefined) continue;
		sessions.push({ id, path: join(dir, name), modifiedAt: info.mtimeMs });
	}
	return sessions.sort((left, right) => right.modifiedAt - left.modifiedAt);
}

export async function latestSession(
	dir: string,
): Promise<SessionInfo | undefined> {
	return (await listSessions(dir))[0];
}

/** Impede que `--session` escape do diretório de sessões. */
export function assertSessionId(id: string): void {
	if (!ID_PATTERN.test(id)) {
		throw new Error(
			`id de sessão inválido: ${id} (use letras, números, ponto, hífen)`,
		);
	}
}

