import { defaultSessionDir, assertSessionId } from "../agent/sessions.js";

export const USAGE = `durable-pi — agente de código com sessão durável

Uso:
  durable-pi -p "<prompt>" [opções]

Opções:
  -p, --print <texto>     prompt; sem modo interativo no M0
      --model <p/m>       provider/modelo (ou DURABLE_PI_MODEL)
      --session-dir <d>   diretório das sessões
      --session <id>      abre uma sessão específica
  -c, --continue          continua a sessão mais recente
      --no-session        não grava sessão (diretório temporário)
  -h, --help              esta ajuda
`;

export type PrintOptions = {
	readonly mode: "print";
	readonly prompt: string;
	readonly model: string;
	readonly sessionDir: string;
	readonly sessionId?: string;
	readonly resume: boolean;
	readonly noSession: boolean;
};

export type CliOptions = PrintOptions | { readonly mode: "help" };

export class UsageError extends Error {}

export function parseArgs(
	argv: readonly string[],
	env: NodeJS.ProcessEnv = process.env,
): CliOptions {
	let prompt: string | undefined;
	let model: string | undefined;
	let sessionDir: string | undefined;
	let sessionId: string | undefined;
	let resume = false;
	let noSession = false;
	const words: string[] = [];
	let positionalOnly = false;

	for (let index = 0; index < argv.length; index += 1) {
		const arg = argv[index];
		if (arg === undefined) continue;

		if (positionalOnly) {
			words.push(arg);
			continue;
		}

		switch (arg) {
			case "-h":
			case "--help":
				return { mode: "help" };
			case "--":
				positionalOnly = true;
				break;
			case "-p":
			case "--print":
				prompt = takeValue(argv, index, arg);
				index += 1;
				break;
			case "--model":
				model = takeValue(argv, index, arg);
				index += 1;
				break;
			case "--session-dir":
				sessionDir = takeValue(argv, index, arg);
				index += 1;
				break;
			case "--session":
				sessionId = takeValue(argv, index, arg);
				index += 1;
				break;
			case "-c":
			case "--continue":
				resume = true;
				break;
			case "--no-session":
				noSession = true;
				break;
			default:
				if (arg.startsWith("-")) {
					throw new UsageError(`opção desconhecida: ${arg}`);
				}
				words.push(arg);
		}
	}

	const text = prompt ?? words.join(" ");
	if (text.trim() === "") {
		throw new UsageError("informe um prompt com -p ou como argumento");
	}

	const selectedModel = model ?? env["DURABLE_PI_MODEL"] ?? "";
	if (selectedModel === "") {
		throw new UsageError("informe --model provider/modelo ou DURABLE_PI_MODEL");
	}

	if (noSession && resume) {
		throw new UsageError("--continue não combina com --no-session");
	}
	if (noSession && sessionId !== undefined) {
		throw new UsageError("--session não combina com --no-session");
	}
	if (sessionId !== undefined) {
		assertSessionId(sessionId);
	}

	return {
		mode: "print",
		prompt: text,
		model: selectedModel,
		sessionDir: sessionDir ?? defaultSessionDir(env),
		...(sessionId === undefined ? {} : { sessionId }),
		resume,
		noSession,
	};
}

function takeValue(
	argv: readonly string[],
	index: number,
	flag: string,
): string {
	const value = argv[index + 1];
	if (value === undefined || value === "") {
		throw new UsageError(`${flag} exige um valor`);
	}
	return value;
}

import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { ModelRef } from "@earendil-works/pi-durable";

import { ask, closeAgent, openAgent } from "../agent/harness.js";
import {
	ensureSessionDir,
	latestSession,
	newSessionId,
	sessionPath,
} from "../agent/sessions.js";
import { parseArgs, USAGE, UsageError } from "./args.js";

/** Ponto de entrada do CLI. Devolve o código de saída em vez de chamar `process.exit`. */
export async function main(argv: readonly string[]): Promise<number> {
	let options;
	try {
		options = parseArgs(argv);
	} catch (error) {
		if (error instanceof UsageError) {
			process.stderr.write(`${error.message}\n\n${USAGE}`);
			return 2;
		}
		throw error;
	}

	if (options.mode === "help") {
		process.stdout.write(USAGE);
		return 0;
	}

	const context = BACKGROUND_CONTEXT;
	let model: ModelRef;
	try {
		model = parseModel(options.model);
	} catch (error) {
		if (error instanceof UsageError) {
			process.stderr.write(`${error.message}\n`);
			return 2;
		}
		throw error;
	}

	let dir = options.sessionDir;
	let ephemeral = false;
	if (options.noSession) {
		dir = await mkdtemp(join(tmpdir(), "durable-pi-"));
		ephemeral = true;
	} else {
		await ensureSessionDir(dir);
	}

	let id = options.sessionId;
	if (id === undefined && options.resume) {
		const latest = await latestSession(dir);
		if (latest === undefined) {
			process.stderr.write(`nenhuma sessão em ${dir} para continuar\n`);
			if (ephemeral) await rm(dir, { recursive: true, force: true });
			return 1;
		}
		id = latest.id;
	}
	id ??= newSessionId();

	try {
		const session = await openAgent(
			{ dbPath: sessionPath(dir, id), cwd: process.cwd(), model },
			context,
		);
		try {
			const outcome = await ask(session, options.prompt, context);
			if (outcome.status === "done") {
				process.stdout.write(`${outcome.answer ?? ""}\n`);
				return 0;
			}
			process.stderr.write(
				`sem resposta: ${outcome.reason ?? "unanswered"}\n`,
			);
			return 1;
		} finally {
			await closeAgent(session, context);
		}
	} catch (error) {
		process.stderr.write(`${describe(error)}\n`);
		return 1;
	} finally {
		if (ephemeral) await rm(dir, { recursive: true, force: true });
	}
}

function parseModel(text: string): ModelRef {
	const slash = text.indexOf("/");
	if (slash <= 0 || slash === text.length - 1) {
		throw new UsageError(
			`modelo inválido: ${text} (esperado provider/modelo)`,
		);
	}
	return {
		provider: text.slice(0, slash),
		modelId: text.slice(slash + 1),
	};
}

function describe(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

