import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import {
	createModels,
	fauxAssistantMessage,
	fauxProvider,
	fauxToolCall,
} from "@earendil-works/pi-ai";
import { describe, expect, it } from "vitest";

import {
	ask,
	closeAgent,
	openAgent,
} from "../../src/agent/harness.js";

const context = BACKGROUND_CONTEXT;

async function withDir(run: (dir: string, dbPath: string) => Promise<void>) {
	const dir = await mkdtemp(join(tmpdir(), "durable-agent-"));
	try {
		await run(dir, join(dir, "session.sqlite"));
	} finally {
		await rm(dir, { recursive: true, force: true });
	}
}

/** Harness sobre SQLite real, modelo falso: nenhuma rede no teste. */
async function openFake(dir: string, dbPath: string) {
	const faux = fauxProvider();
	const models = createModels();
	models.setProvider(faux.provider);
	const model = faux.getModel();
	const session = await openAgent(
		{
			dbPath,
			cwd: dir,
			model: { provider: model.provider, modelId: model.id },
			models,
		},
		context,
	);
	return { session, faux };
}

describe("openAgent", () => {
	it("executa a tool write e devolve o texto final", async () => {
		await withDir(async (dir, dbPath) => {
			const { session, faux } = await openFake(dir, dbPath);
			faux.setResponses([
				fauxAssistantMessage([
					fauxToolCall("write", { path: "hello.txt", content: "olá\n" }),
				]),
				fauxAssistantMessage("pronto"),
			]);

			const outcome = await ask(session, "crie hello.txt", context);

			expect(outcome).toMatchObject({ status: "done", answer: "pronto" });
			expect(await readFile(join(dir, "hello.txt"), "utf8")).toBe("olá\n");
			await closeAgent(session, context);
		});
	});

	it("persiste o transcript e reabre a mesma conversa", async () => {
		await withDir(async (dir, dbPath) => {
			const first = await openFake(dir, dbPath);
			first.faux.setResponses([fauxAssistantMessage("primeira resposta")]);
			await ask(first.session, "oi", context);
			const before = await first.session.conversation.context(context);
			await closeAgent(first.session, context);

			const second = await openFake(dir, dbPath);
			const after = await second.session.conversation.context(context);

			expect(after.entries.length).toBe(before.entries.length);
			expect(after.messages.length).toBeGreaterThan(0);
			await closeAgent(second.session, context);
		});
	});

	it("reporta desfecho sem resposta quando o modelo falha", async () => {
		await withDir(async (dir, dbPath) => {
			const { session, faux } = await openFake(dir, dbPath);
			faux.setResponses([
				fauxAssistantMessage("x", { errorMessage: "provedor fora do ar" }),
			]);

			const outcome = await ask(session, "oi", context);

			expect(outcome.status).toBe("unanswered");
			expect(outcome.reason).toBeDefined();
			await closeAgent(session, context);
		});
	});
});

import { describe, expect, it } from "vitest";

import { parseArgs, UsageError } from "../../src/cli/args.js";

const env = { DURABLE_PI_SESSION_DIR: "/tmp/sessions" };

describe("parseArgs", () => {
	it("lê prompt por -p e modelo por --model", () => {
		const options = parseArgs(
			["-p", "crie x", "--model", "opencode-go/modelo", "--session-dir", "/d"],
			env,
		);
		expect(options).toEqual({
			mode: "print",
			prompt: "crie x",
			model: "opencode-go/modelo",
			sessionDir: "/d",
			resume: false,
			noSession: false,
		});
	});

	it("aceita o prompt posicional e o modelo do ambiente", () => {
		const options = parseArgs(["explique", "o", "repo"], {
			...env,
			DURABLE_PI_MODEL: "p/m",
		});
		expect(options).toMatchObject({ prompt: "explique o repo", model: "p/m" });
	});

	it("carrega --session, --continue e --no-session", () => {
		expect(
			parseArgs(["-p", "x", "--model", "p/m", "--session", "abc"], env),
		).toMatchObject({ sessionId: "abc" });
		expect(parseArgs(["-p", "x", "--model", "p/m", "-c"], env)).toMatchObject({
			resume: true,
		});
		expect(
			parseArgs(["-p", "x", "--model", "p/m", "--no-session"], env),
		).toMatchObject({ noSession: true });
	});

	it("recusa prompt vazio, opção desconhecida e modelo ausente", () => {
		expect(() => parseArgs(["--model", "p/m"], env)).toThrow(UsageError);
		expect(() => parseArgs(["-p", "x", "--nope"], env)).toThrow(UsageError);
		expect(() => parseArgs(["-p", "x"], env)).toThrow(UsageError);
	});

	it("recusa combinações incoerentes", () => {
		expect(() =>
			parseArgs(["-p", "x", "--model", "p/m", "-c", "--no-session"], env),
		).toThrow(UsageError);
		expect(() =>
			parseArgs(["-p", "x", "--model", "p/m", "--session", "../fora"], env),
		).toThrow(/inválido/);
	});

	it("devolve ajuda sem exigir prompt", () => {
		expect(parseArgs(["--help"], env)).toEqual({ mode: "help" });
	});
});

