import { spawnSync } from "node:child_process";
import { chmod, mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const SCRIPT = fileURLToPath(new URL("../../scripts/run.sh", import.meta.url));

async function fakeBin(dir: string, name: string): Promise<string> {
	const path = join(dir, name);
	await writeFile(path, "#!/bin/sh\nexit 0\n");
	await chmod(path, 0o755);
	return path;
}

type Setup = { dir: string; bin: string; config: string };

async function withSetup(run: (setup: Setup) => Promise<void>) {
	const dir = await mkdtemp(join(tmpdir(), "durable-run-"));
	try {
		const bin = join(dir, "bin");
		await mkdir(bin);
		await run({ dir, bin, config: join(dir, "container.conf") });
	} finally {
		await rm(dir, { recursive: true, force: true });
	}
}

function runtimeInfo(env: Record<string, string>) {
	const result = spawnSync("bash", [SCRIPT, "--runtime-info"], {
		env: { PATH: "/usr/bin:/bin", HOME: "/nonexistent", ...env },
		encoding: "utf8",
	});
	return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}
```

