import { open, readFile, rm } from "node:fs/promises";

export type StorageLock = { readonly path: string; release(): Promise<void> };

export async function acquireStorageLock(dbPath: string): Promise<StorageLock> {
	const path = `${dbPath}.lock`;
	for (let attempt = 0; attempt < 2; attempt += 1) {
		try {
			const handle = await open(path, "wx");
			await handle.writeFile(`${process.pid}\n`, "utf8");
			await handle.close();
			return {
				path,
				release: async () => { await rm(path, { force: true }); },
			};
		} catch (error) {
			if (!isErrno(error, "EEXIST")) throw error;
			const owner = await readOwner(path);
			if (owner !== undefined && isAlive(owner)) {
				throw new Error(`sessão em uso pelo processo ${owner} (${path})`);
			}
			// lock órfão: remove e tenta de novo
			await rm(path, { force: true });
		}
	}
	throw new Error(`não foi possível obter o lock ${path}`);
}

async function readOwner(path: string): Promise<number | undefined> {
	try {
		const text = await readFile(path, "utf8");
		const pid = Number.parseInt(text.trim(), 10);
		return Number.isInteger(pid) && pid > 0 ? pid : undefined;
	} catch { return undefined; }
}

function isAlive(pid: number): boolean {
	try { process.kill(pid, 0); return true; } catch { return false; }
}
