export function newSessionId(now: Date = new Date()): string {
	const stamp = now
		.toISOString()
		.replace(/\.\d+Z$/, "")
		.replace(/[-:]/g, "");
	return `${stamp}-${randomBytes(3).toString("hex")}`;
}
