import { DatabaseSync } from "node:sqlite";

export type StorageLock = {
	readonly path: string;
	release(): Promise<void>;
};

/**
 * Lock exclusivo por arquivo de storage.
 *
 * `pi-durable` exige um dono por banco. Evitar isso com arquivo/PID não é
 * confiável: existe janela entre criar e escrever, e PID não identifica dono
 * entre containers. Socket unix também não fecha: remover o socket de um dono
 * morto pode apagar o socket de um dono novo (race entre `unlink` e `listen`).
 *
 * Aqui a exclusão é uma transação `BEGIN EXCLUSIVE` num SQLite separado
 * (`<db>.lock`), mantida aberta enquanto o Harness está aberto. O lock é do
 * kernel, liberado automaticamente quando o processo morre — sem PID, sem
 * relógio, sem arquivo órfão para detectar.
 */
export async function acquireStorageLock(dbPath: string): Promise<StorageLock> {
	const path = `${dbPath}.lock`;
	const db = new DatabaseSync(path);

	try {
		// Sem espera: quem não consegue o lock precisa falhar agora, não travar.
		db.exec("PRAGMA busy_timeout = 0");
		db.exec("BEGIN EXCLUSIVE");
		// Uma escrita garante a exclusividade mesmo se o journal for WAL.
		db.exec("CREATE TABLE IF NOT EXISTS owner (id INTEGER)");
		db.exec("DELETE FROM owner");
	} catch (error) {
		db.close();
		if (isBusy(error)) {
			throw new Error(
				`sessão em uso por outro processo (${path}); feche-o antes de abrir de novo`,
			);
		}
		throw error;
	}

	return {
		path,
		release: async () => {
			try {
				db.exec("ROLLBACK");
			} finally {
				db.close();
			}
		},
	};
}

/** SQLite sinaliza concorrência com `SQLITE_BUSY` (5). */
function isBusy(error: unknown): boolean {
	return (
		typeof error === "object" &&
		error !== null &&
		"errcode" in error &&
		error.errcode === 5
	);
}

import { spawn } from "node:child_process";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { acquireStorageLock } from "../../src/agent/lock.js";

async function withDb(run: (dbPath: string) => Promise<void>) {
	const dir = await mkdtemp(join(tmpdir(), "durable-lock-"));
	try {
		await run(join(dir, "session.sqlite"));
	} finally {
		await rm(dir, { recursive: true, force: true });
	}
}

/** Processo filho que segura o lock até ser morto. */
function holdUntilKilled(dbPath: string): Promise<import("node:child_process").ChildProcess> {
	const script = `
		import("node:sqlite").then(({ DatabaseSync }) => {
			const db = new DatabaseSync(${JSON.stringify(`${dbPath}.lock`)});
			db.exec("PRAGMA busy_timeout = 0");
			db.exec("BEGIN EXCLUSIVE");
			db.exec("CREATE TABLE IF NOT EXISTS owner (id INTEGER)");
			console.log("segurando");
			setInterval(() => {}, 1000);
		});
	`;
	return new Promise((resolve, reject) => {
		const child = spawn(process.execPath, ["-e", script], {
			stdio: ["ignore", "pipe", "pipe"],
		});
		child.stdout.once("data", () => resolve(child));
		child.once("error", reject);
	});
}

describe("acquireStorageLock", () => {
	it("recusa um segundo dono enquanto o primeiro está aberto", async () => {
		await withDb(async (dbPath) => {
			const lock = await acquireStorageLock(dbPath);
			await expect(acquireStorageLock(dbPath)).rejects.toThrow(
				/em uso por outro processo/,
			);
			await lock.release();
		});
	});

	it("libera o banco depois do release", async () => {
		await withDb(async (dbPath) => {
			const first = await acquireStorageLock(dbPath);
			await first.release();

			const second = await acquireStorageLock(dbPath);
			expect(second.path).toBe(`${dbPath}.lock`);
			await second.release();
		});
	});

	it("toma o lock de um processo que morreu", async () => {
		await withDb(async (dbPath) => {
			const child = await holdUntilKilled(dbPath);
			await expect(acquireStorageLock(dbPath)).rejects.toThrow(/em uso/);

			child.kill("SIGKILL");
			await new Promise((resolve) => child.once("exit", resolve));

			const lock = await acquireStorageLock(dbPath);
			await lock.release();
		});
	});

	it("vários concorrentes: só um ganha", async () => {
		await withDb(async (dbPath) => {
			const results = await Promise.allSettled([
				acquireStorageLock(dbPath),
				acquireStorageLock(dbPath),
				acquireStorageLock(dbPath),
